  const timestamp = new Date().toISOString();
  const line = `[${timestamp}] ${message}`;
  console.log(line);
}

async function main(): Promise<void> {
  log("=== Composio Trigger Lifecycle Management ===");
  log(`User ID: ${USER_ID}`);
  log(`Toolkit: ${TOOLKIT}`);

  // Step 1: Initialize Composio and create a session for zealt-user01
  log("\n[STEP 1] Initializing Composio SDK...");
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY,
  });

  // createSession returns a scoped Composio instance (with custom headers if needed)
  const session = composio.createSession();
  log("Composio session created successfully.");

  // Step 2: List available trigger types for the github toolkit
  log(`\n[STEP 2] Listing available trigger types for toolkit: ${TOOLKIT}...`);
  const triggerTypesResponse = await session.triggers.listTypes({
    toolkits: [TOOLKIT],
  });

  const triggerTypes = triggerTypesResponse.items ?? [];
  log(`Found ${triggerTypes.length} trigger type(s) for '${TOOLKIT}':`);
  triggerTypes.forEach((t, i) => {
    log(`  [${i + 1}] slug=${t.slug} | name=${t.name}`);
  });

  // Resolve the trigger slug: prefer exact match, fallback to first available
  let chosenTriggerSlug = TRIGGER_SLUG;
  const exactMatch = triggerTypes.find(
    (t) => t.slug.toUpperCase() === TRIGGER_SLUG.toUpperCase()
  );
  if (!exactMatch) {
    if (triggerTypes.length === 0) {
      throw new Error(
        `No trigger types found for toolkit '${TOOLKIT}'. Cannot proceed.`
      );
    }
    chosenTriggerSlug = triggerTypes[0].slug;
    log(
      `Warning: '${TRIGGER_SLUG}' not found. Using fallback: '${chosenTriggerSlug}'`
    );
  } else {
    log(`Selected trigger type: '${chosenTriggerSlug}'`);
  }

  // Step 3: Create (activate) the trigger for the user
  log(`\n[STEP 3] Creating trigger '${chosenTriggerSlug}' for user '${USER_ID}'...`);
  const createResponse = await session.triggers.create(
    USER_ID,
    chosenTriggerSlug,
    {}
  );

  const triggerId = createResponse.id;
  log(`Trigger created successfully!`);
  log(`  trigger_id : ${triggerId}`);
  log(`  trigger    : ${JSON.stringify(createResponse, null, 2)}`);

  // Step 4: Disable the newly created trigger
  log(`\n[STEP 4] Disabling trigger '${triggerId}'...`);
  const disableResponse = await session.triggers.disable(triggerId);
  log(`Trigger disabled successfully!`);
  log(`  disable_response: ${JSON.stringify(disableResponse, null, 2)}`);

  // Step 5: List active triggers and verify the trigger is no longer active
  log(`\n[STEP 5] Listing active triggers (showDisabled=true to verify status)...`);
  const activeTriggers = await session.triggers.listActive({
    triggerIds: [triggerId],
    showDisabled: true,
  });

  const triggerItems = activeTriggers.items ?? [];
  log(`Total triggers returned: ${triggerItems.length}`);

  let foundTrigger = triggerItems.find((t) => t.id === triggerId);
  let isDisabled: boolean;
  let verificationStatus: string;

  if (!foundTrigger) {
    // Trigger not in the list at all → effectively disabled / removed
    isDisabled = true;
    verificationStatus = "NOT_FOUND_IN_ACTIVE_LIST (considered disabled)";
    log(`Trigger '${triggerId}' is NOT present in the active triggers list.`);
  } else {
    isDisabled = foundTrigger.disabledAt !== null;
    verificationStatus = isDisabled
      ? `DISABLED (disabledAt=${foundTrigger.disabledAt})`
      : "STILL_ACTIVE";
    log(
      `Trigger '${triggerId}' status: ${verificationStatus}`
    );
  }

  log(
    `\nVerification result: Trigger is ${isDisabled ? "DISABLED ✓" : "STILL ACTIVE ✗"}`
  );

  // Step 6: Save trigger details and final status to JSON
  log(`\n[STEP 6] Saving trigger details to '${OUTPUT_FILE}'...`);

  const outputData = {
    user_id: USER_ID,
    toolkit: TOOLKIT,
    trigger_slug: chosenTriggerSlug,
    trigger_id: triggerId,
    created_at: new Date().toISOString(),
    trigger_types_available: triggerTypes.map((t) => ({
      slug: t.slug,
      name: t.name,
      description: t.description,
    })),
    create_response: createResponse,
    disable_response: disableResponse,
    final_status: {
      trigger_id: triggerId,
      is_disabled: isDisabled,
      verification_status: verificationStatus,
      active_triggers_after_disable: triggerItems,
    },
  };

  fs.writeFileSync(OUTPUT_FILE, JSON.stringify(outputData, null, 2), "utf-8");
  log(`Output saved to: ${OUTPUT_FILE}`);

  log("\n=== Trigger Lifecycle Management Complete ===");
  log(`Summary:`);
  log(`  - Listed ${triggerTypes.length} trigger type(s) for '${TOOLKIT}'`);
  log(`  - Created trigger: ${triggerId} (slug: ${chosenTriggerSlug})`);
  log(`  - Disabled trigger: ${triggerId}`);
  log(`  - Verification: ${verificationStatus}`);
  log(`  - Output JSON: ${OUTPUT_FILE}`);
}

main().catch((err: Error) => {
  log(`\n[ERROR] ${err.message}`);
  if (err.stack) {
    log(err.stack);
  }
  process.exit(1);
});

